 rows=[dict(word=w['word'],pos='adj',ipa=w['ipa'],gloss={'felicitous':'Well chosen and suitable.','infelicitous':'Unsuitable or awkwardly chosen.'}[w['word']],meaning_zh=w['meaning'],etymology_text={'felicitous':'English felicity + -ous.','infelicitous':'English negative in- + felicitous.'}[w['word']],sources=w['sources']) for w in W if w['word']!='felicity'];Path('.cache/batch200/root_felic_supplement_request.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
